	private LmdbNativeCompiledTruth compileSameTerm(SameTerm sameTerm) {
		LmdbNativeCompiledId left = compileId(sameTerm.getLeftArg());
		LmdbNativeCompiledId right = compileId(sameTerm.getRightArg());
		if (left == null || right == null) {
			return null;
		}
		boolean checkLeft = mayBeUnbound(left.requiredMask);
		boolean checkRight = mayBeUnbound(right.requiredMask);
		return truth(left.requiredMask | right.requiredMask, row -> {
			long l = left.evaluator.eval(row);
			long r = right.evaluator.eval(row);
			// sameTerm over an unbound argument is a SPARQL type error, so NOT must not flip it to TRUE
			if (checkLeft && (l == NativeLmdbQuerySource.UNKNOWN_ID || l == 0L)) {
				return ERROR;
			}
			if (checkRight && (r == NativeLmdbQuerySource.UNKNOWN_ID || r == 0L)) {
				return ERROR;
			}
			return l == r ? TRUE : FALSE;
		});
	}

	private LmdbNativeCompiledTruth compileCompare(Compare compare) {
		LmdbNativeCompiledValue left = compileValue(compare.getLeftArg());
		LmdbNativeCompiledValue right = compileValue(compare.getRightArg());
		if (left == null || right == null || !anchoredComparison(compare.getLeftArg(), compare.getRightArg())) {
			return null;
		}
		Compare.CompareOp op = compare.getOperator();
		boolean strict = strictCompare;
		return truth(left.requiredMask | right.requiredMask, row -> LmdbNativeExpressionOps
				.compareValues(left.evaluator.eval(row), right.evaluator.eval(row), op, strict));
	}

	private boolean anchoredComparison(ValueExpr left, ValueExpr right) {
		return anchoredValue(left) || anchoredValue(right);
	}

	private boolean anchoredValue(ValueExpr expr) {
		if (expr instanceof ValueConstant) {
			return comparableConstant(((ValueConstant) expr).getValue());
		}
		if (expr instanceof Var && ((Var) expr).hasValue()) {
			return comparableConstant(((Var) expr).getValue());
		}
		if (expr instanceof MathExpr || expr instanceof Str || expr instanceof Lang || expr instanceof Datatype) {
			return true;
		}
		if (expr instanceof If || expr instanceof Coalesce) {
			return true;
		}
		if (expr instanceof FunctionCall) {
			LmdbNativeFunctionLibrary.Entry entry = LmdbNativeFunctionLibrary.entry(((FunctionCall) expr).getURI());
			return entry != null && entry.comparableResult;
		}
		return false;
	}

	private boolean comparableConstant(Value value) {
		LmdbNativeValueCodec.DecodedValue decoded = LmdbNativeValueCodec.fromValue(value);
		return decoded.numeric() || decoded.stringLiteral();
	}

